---parse_rewards
---@param ids string
---@param nums string
---@param split string | nil @ default ;
---@return table[] @ { goodsId : integer, goodsNum : integer }
function parse_rewards(ids, nums, split)
    if isNull(split) or string.isEmpty(split) then
        split = ';'
    end
    local rewards = {}
    local idLists = string.split(ids, split)
    local numsLists = string.split(nums, split)
    local len = math.min(#idLists, #numsLists)
    for i = 1, len do
        if checkNumber(idLists[i]) > 0 then
            table.insert(rewards, {
                goodsId = checkNumber(idLists[i]),
                goodsNum = checkNumber(numsLists[i])
            })
        end
    end
    return rewards
end

---parse_rewards2
---@param ids string
---@param nums string
---@param split string | nil @ default ;
---@return table[] @ { goodsId : integer, num : integer }
function parse_rewards2(ids, nums, split)
    local rewards = parse_rewards(ids, nums, split)
    for _, v in ipairs(rewards) do
        v.num = v.goodsNum
        v.goodsNum = nil
    end
    return rewards
end

