end

---format4bit
---格式化4位数字
---@param num number
---@param maxNo number
---@return string
function format4bit(num, maxNo)
    if isNull(maxNo) then
        maxNo = 999
    end
    local text = tostring(num)
    if checkNumber(num) > maxNo then
        text = "999+"
    end
    return text
end

---parse_number
---@param row TableML.TableFileRow
---@param header_name string
---@param defaultV number
---@return number
function parse_number(row, header_name, defaultV)
    local ret = 0
    if not isNull(defaultV) then
        ret = tonumber(defaultV)
    end
    local v = row:Get(header_name, defaultV == nil)
    if not string.isEmpty(v) then
        ret = tonumber(v) or 0
    end
    return ret
end

