---parseTwoDelimiterStr2Dict
---解析两个分割数字符串->dict
function parseTwoDelimiterStr2Dict(str, delimiter1, delimiter2)
    delimiter1 = delimiter1 or ";"
    delimiter2 = delimiter2 or ":"
    local t = {}
    local strSplit = string.split
    local list = strSplit(str, delimiter1)
    if next(list) ~= nil then
        local checkNumber = checkNumber
        for _, v in pairs(list) do
            local attrPair = strSplit(v, delimiter2)
            if #attrPair == 2 then
                ---排除不为2长度的
                local attrAddId, attrV = attrPair[1], attrPair[2]
                t[checkNumber(attrAddId)] = checkNumber(attrV)
            end
        end
    end
    return t
end

function parse_vector3(row, rowName, delimiter)
    return Vector3.New(SafeUnpack(Tools.splitToNum(parse_string(row,rowName, ''), delimiter or ';')))
end

function parse_vector3s(row, rowName, delimiter1, delimiter2)
    local posList = parse_strings(parse_string(row, rowName, ""), delimiter1 or ";")
    local vector3s = {}
    for i, pos in ipairs(posList) do
        table.insert(vector3s, Vector3.New(SafeUnpack(Tools.splitToNum(pos, pos or ','))))
    end
    return vector3s
end

---attribute_format
---格式化字符串为百分比还是只显示数字
---@param convertToPercent number
---@param value number
---@return string
function attribute_format(convertToPercent, value)
    local checkInt = checkInt
    local isConvert = checkInt(convertToPercent) > 0
    local v = math.abs(checkNumber(value))
    if isConvert then
        --- 百分比显示 多保留一位小数
        --- 2022-05-17 不在向下取整改为四舍五入   
        return string.format('%g%%', checkInt(v * 10000) / 100)
    else
        ---fix:1216.08 - 1016.08 使用 math.floor 199的问题
        return tostring(num_floor(v, 0.001))
    end
end

function num_floor(value, diff)
    local v1, v2 = math.modf(value)
    if strict_number_equal(v2, 1, diff) then
        v1 = v1 + 1
    end
    return v1
end

function format_tens_place(number)
    number = checkNumber(number)
    local fmt = number < 10 and '0' or ''
    return fmt .. number
end

---sortByKey
---根据key排序
---@param t table
---@param asc boolean
---@return table
function sortByKey(t, asc)
    local temp = {}
    for key, _ in pairs(t) do
        table.insert(temp, key)
    end
    if asc then
        table.sort(temp, function(a, b)
            return checkNumber(a) > checkNumber(b)
        end)
    else
        table.sort(temp, function(a, b)
            return checkNumber(a) < checkNumber(b)
        end)
    end
    return temp
end

--- 严格比较number是否相等
---@param num1 number
---@param num2 number
---@param diff? number
---@return boolean
function strict_number_equal(num1, num2, diff)
    local equalNum1 = checkNumber(num1)
    local equalNum2 = checkNumber(num2)
    diff = diff or 0.0000001
    return math.abs(equalNum1 - equalNum2) < diff
end

