CommonChecker = function(a, b, fieldNames, asc, customAscConfig, customGetFieldFunc)
    customAscConfig = customAscConfig or {}
    local checkNumber = checkNumber
    local fieldNameCount = #fieldNames
    local loopTimes = fieldNameCount
    for i = 1, loopTimes do
        local fieldName    = fieldNames[i]
        local getFieldFunc = customGetFieldFunc ~= nil and customGetFieldFunc[fieldName] or nil
        local aFiled, bFiled
        if getFieldFunc then
            aFiled, bFiled = getFieldFunc(a), getFieldFunc(b)
        else
            aFiled, bFiled = checkNumber(a[fieldName]), checkNumber(b[fieldName])
        end
        --- 循环到最后一个 强制检查
        if aFiled ~= bFiled or i == loopTimes then
            local customAsc = customAscConfig[fieldName]
            local isCustom = customAsc ~= nil
            if isCustom then
                if customAsc then
                    return aFiled > bFiled
                else
                    return aFiled < bFiled
                end
            else
                if asc then
                    return aFiled > bFiled
                else
                    return aFiled < bFiled
                end
            end
        end
    end
end

