---@param callback fun():void
---@return Engine.Lib.CoWait
function CoWaitDo(callback)
    local util = require 'XLua.util'
    return CoWait.Start():Coroutine(util.cs_generator(function()
        if callback then
            callback()
        end
    end))
end

---@param callback fun():void
---@return UnityEngine.Coroutine
function CoStart(callback)
    if isNull(callback) then return end
    local cs_coroutine = require('XLua.cs_coroutine')
    return cs_coroutine.start(callback)
end

---@param coroutine UnityEngine.Coroutine
function CoStop(coroutine)
    if isNull(coroutine) then return end
    local cs_coroutine = require('XLua.cs_coroutine')
    cs_coroutine.stop(coroutine)
end

--- default is EndOfFrame
---@param seconds number | System.Collections.IEnumerator | nil
---@return any
function CoYield(seconds)
    if seconds then
        if type(seconds) == 'number' then
            return coroutine.yield(Yielders.GetWaitForSeconds(checkNumber(seconds)))
        else
            return coroutine.yield(seconds)
        end
    else
        return coroutine.yield(Yielders.EndOfFrame)
    end
end

