--- 设置 列表组件 的 刷新事件函数
---@param listView SuperScrollView.LoopListView2
---@param callback fun(listView:SuperScrollView.LoopListView2, luaIndex:integer):SuperScrollView.LoopListViewItem2
---@param prefabName string | nil @ 元素名，用于计算列表viewPort显示多少个
---@param initParam table | nil @ 自定义初始化数据 @see SuperScrollView.LoopListViewInitParam
function SetListViewAction(listView, callback, prefabName, initParam)
    if isNull(listView) then return end
    if not listView.IsListViewInit then
        ---@type SuperScrollView.LoopListViewInitParam
        local listInitParam = nil
        if initParam ~= nil then
            if prefabName and initParam.autoSize then
                local listItemData  = listView:GetItemPrefabConfData(prefabName)
                local itemSizeDelta = listItemData.mItemPrefab.transform.sizeDelta
                local listItemSize  = listView.IsVertList and itemSizeDelta.y or itemSizeDelta.x
                initParam.mItemDefaultWithPaddingSize = listItemSize + listItemData.mPadding
                initParam.autoSize = nil
            end
            local LoopListViewInitParam = CS.SuperScrollView.LoopListViewInitParam
            listInitParam = LoopListViewInitParam.CopyDefaultInitParam()
            for k, v in pairs(initParam) do
                listInitParam[k] = v
            end
        end
        listView:InitListView(0, function(listView, listIndex)
            if listIndex < 0 then return nil end
            local luaIndex = listIndex + 1
            return callback(listView, luaIndex)
        end, listInitParam)
        if prefabName and iskindof(listView, typeof(CS.SuperScrollView.LoopListView2)) then
            listView:UpdateDisplayItemCount(prefabName)
        end
    end
end


