function BinarySearchLeftBound(left, right, target, func)
    local floor = math.floor
    while left <= right do
        local middle = left + floor((right - left) * 0.5)
        if target < func(middle) then
            right = middle - 1
        else
            left = middle + 1
        end
    end
    return right
end


